import{_ as t,c as e,o as r,ah as i}from"./chunks/framework.BaYrGl-1.js";const p=JSON.parse('{"title":"第一章 软件设计基础","description":"介绍什么是良好的软件设计、设计原则与设计模式的关系、面向对象设计的核心思想等基础概念。","frontmatter":{"title":"第一章 软件设计基础","date":"2025-11-19T00:00:00.000Z","description":"介绍什么是良好的软件设计、设计原则与设计模式的关系、面向对象设计的核心思想等基础概念。"},"headers":[],"relativePath":"series/软件设计体系结构/01-软件设计基础.md","filePath":"series/软件设计体系结构/01-软件设计基础.md","lastUpdated":1763647603000}'),l={name:"series/软件设计体系结构/01-软件设计基础.md"};function o(s,a,n,_,d,h){return r(),e("div",null,a[0]||(a[0]=[i('<h1 id="第一章-软件设计基础" tabindex="-1">第一章 软件设计基础 <a class="header-anchor" href="#第一章-软件设计基础" aria-label="Permalink to &quot;第一章 软件设计基础&quot;">​</a></h1><h2 id="_1-1-什么是良好的软件设计" tabindex="-1">1.1 什么是良好的软件设计？ <a class="header-anchor" href="#_1-1-什么是良好的软件设计" aria-label="Permalink to &quot;1.1 什么是良好的软件设计？&quot;">​</a></h2><p>良好的软件设计应该具备以下特征：</p><ul><li><strong>可维护性</strong>：代码易于理解和修改</li><li><strong>可扩展性</strong>：系统能够容易地加入新功能</li><li><strong>可复用性</strong>：代码可以在不同项目中复用</li><li><strong>可测试性</strong>：易于编写单元测试</li><li><strong>性能</strong>：满足性能要求</li></ul><h2 id="_1-2-设计原则与设计模式的关系" tabindex="-1">1.2 设计原则与设计模式的关系 <a class="header-anchor" href="#_1-2-设计原则与设计模式的关系" aria-label="Permalink to &quot;1.2 设计原则与设计模式的关系&quot;">​</a></h2><p>设计原则是指导设计的基本规则，而设计模式是在特定情境下应用这些原则的具体解决方案。</p><h2 id="_1-3-面向对象设计的核心思想" tabindex="-1">1.3 面向对象设计的核心思想 <a class="header-anchor" href="#_1-3-面向对象设计的核心思想" aria-label="Permalink to &quot;1.3 面向对象设计的核心思想&quot;">​</a></h2><p>面向对象设计的核心包括：</p><ul><li><strong>抽象</strong>：提取对象的共同特征</li><li><strong>封装</strong>：隐藏实现细节</li><li><strong>继承</strong>：共享共同特征</li><li><strong>多态</strong>：同一接口的不同实现</li></ul><h2 id="_1-4-软件演化与可维护性的重要性" tabindex="-1">1.4 软件演化与可维护性的重要性 <a class="header-anchor" href="#_1-4-软件演化与可维护性的重要性" aria-label="Permalink to &quot;1.4 软件演化与可维护性的重要性&quot;">​</a></h2><p>软件在生命周期中不断演化，良好的设计能够：</p><ul><li>降低维护成本</li><li>减少引入缺陷的风险</li><li>提高开发效率</li></ul><hr><p>更多内容敬请期待...</p>',14)]))}const u=t(l,[["render",o]]);export{p as __pageData,u as default};
